'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const minute = s => { if (s === '—') return Infinity; const [h,m]=s.split(':').map(Number); return (h < 6 ? h+24 : h)*60+m; };
const acts = venues.flatMap(([venue,street,note,sets],vi)=>sets.map(([start,end,name,bio],i)=>({id:`${vi}-${i}`,venue,street,note,start,end,name,bio,late:minute(start)>=1320,pending:false})));
pending.forEach(([start,end,name,bio],i)=>acts.push({id:`pending-${i}`,venue:i===0?'Chalk':'Green Door Store',start,end,name,bio,pending:true}));
let saved;
try { const data=JSON.parse(localStorage.getItem('mutations26-saturday')||'[]'); saved=new Set(Array.isArray(data)?data.filter(id=>acts.some(a=>a.id===id)):[]); } catch {saved=new Set();}
let mode='venues', venue='all', query='', period='all';
const spotifyIcon='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="12" r="12"/><g fill="none" stroke="#f3f2e9" stroke-width="1.5" stroke-linecap="round"><path d="M5 9c5-2 10-1 14 1M6 13c4-1.5 8-1 12 1M7 17c3-1 6-.7 9 .5"/></g></svg>';
function announce(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(announce.timer);announce.timer=setTimeout(()=>$('#toast').hidden=true,2600);}
function clashes(act){return !act.pending ? acts.filter(a=>a.id!==act.id&&saved.has(a.id)&&!a.pending&&minute(a.start)<minute(act.end)&&minute(a.end)>minute(act.start)):[];}
function card(a,showVenue=false){const isSaved=saved.has(a.id), overlap=isSaved?clashes(a):[];const listening=a.name==='Beastie Boys Club Night'?'Beastie Boys':a.name==='Mike D 5D'?'Mike D':a.name;return `<article class="set"><div class="time">${esc(a.start)}<small>${a.pending?'TIME TBA':`until ${esc(a.end)}`}</small>${!a.pending&&minute(a.start)>=1440?'<div class="late">SUN 25 OCT</div>':''}</div><div>${showVenue?`<div class="venue-label">${esc(a.venue)}</div>`:''}<div class="bandline"><h4>${esc(a.name)}</h4><span class="badge">${a.pending?'Official venue · time TBA':a.late?'Provisional · late set':'Provisional'}</span></div><p class="bandinfo">${esc(a.bio)}</p><div class="links"><a class="spotify" href="https://open.spotify.com/search/${encodeURIComponent(listening)}" target="_blank" rel="noopener" aria-label="Search Spotify for ${esc(listening)}">${spotifyIcon}Find on Spotify ↗</a><a class="profile" href="https://mutationsfestival.com/" target="_blank" rel="noopener">Festival artist list ↗</a></div>${overlap.length?`<div class="clash">↗ Overlaps with ${esc(overlap.map(x=>x.name).join(', '))}</div>`:''}</div><button class="save ${isSaved?'saved':''}" data-save="${a.id}" aria-label="${isSaved?'Remove':'Save'} ${esc(a.name)} ${esc(a.start)} ${esc(a.venue)}" aria-pressed="${isSaved}">${isSaved?'★':'☆'}</button></article>`;}
function filtered(){return acts.filter(a=>(venue==='all'||a.venue===venue)&&(`${a.name} ${a.venue}`.toLowerCase().includes(query))&&(mode!=='saved'||saved.has(a.id))&&(period==='all'||period==='pending'&&a.pending||!a.pending&&(period==='afternoon'&&minute(a.start)<1080||period==='evening'&&minute(a.start)>=1080&&minute(a.start)<1320||period==='late'&&minute(a.start)>=1320)));}
function render(){
clearVenueMap();
const items=filtered();$('#savedcount').textContent=saved.size;
$('#viewtitle').textContent=mode==='map'?'Find your way around':mode==='saved'?'Your Saturday, your way':mode==='time'?'From first set to last':venue==='all'?'The Saturday lineup':venue;
$('#resultcount').textContent=`${items.length} sets · ${new Set(items.map(x=>x.name)).size} acts${mode==='saved'?' saved in this browser':' · community times, subject to change'}`;
document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});
$('#venuelist').innerHTML=[['all','All venues',acts.length],...venues.map(v=>[v[0],v[0],acts.filter(a=>a.venue===v[0]).length])].map(([key,label,n])=>`<button class="venuebtn ${venue===key?'active':''}" data-venue="${esc(key)}" aria-pressed="${venue===key}">${esc(label)}<span>${String(n).padStart(2,'0')}</span></button>`).join('');
$('#mobilevenue').value=venue;
if(!items.length){$('#results').innerHTML=`<div class="empty"><strong>${mode==='saved'&&!saved.size?'Make room for a new favourite.':'No sets match these filters.'}</strong><p>${mode==='saved'&&!saved.size?'Tap ☆ beside any act to add a set to your day.':'Try another venue, search or time of day.'}</p><button class="outline" id="reset">${mode==='saved'&&!saved.size?'Explore the lineup':'Clear filters'}</button></div>`;return;}
if(mode==='map'){renderVenueMap(items);return;}
if(mode==='venues'){$('#results').innerHTML=venues.filter(v=>items.some(a=>a.venue===v[0])).map(([name,street,note])=>`<section class="group"><header class="venuehead"><div><h3>${esc(name)}</h3><p>${esc(street)} &nbsp; / &nbsp; ${esc(note)}</p></div><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(name+' Brighton')}" target="_blank" rel="noopener" aria-label="Directions to ${esc(name)}">Directions ↗</a></header>${items.filter(a=>a.venue===name).sort((a,b)=>minute(a.start)-minute(b.start)).map(a=>card(a)).join('')}</section>`).join('');}
else{$('#results').innerHTML=`<section class="group timeline">${items.sort((a,b)=>minute(a.start)-minute(b.start)||a.venue.localeCompare(b.venue)).map(a=>card(a,true)).join('')}</section>`;}
}
$('#mobilevenue').innerHTML='<option value="all">All venues</option>'+venues.map(v=>`<option value="${esc(v[0])}">${esc(v[0])}</option>`).join('');
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]'),v=e.target.closest('[data-venue]'),tab=e.target.closest('[data-mode]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('mutations26-saturday',JSON.stringify([...saved]));}catch{announce('Saved for this session. Browser storage is unavailable.');}render();document.querySelector(`[data-save="${id}"]`)?.focus();}if(v){venue=v.dataset.venue;render();}if(tab){mode=tab.dataset.mode;render();}if(e.target.closest('#reset')){query='';venue='all';period='all';$('#search').value='';$('#period').value='all';if(!saved.size)mode='venues';render();}});
$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render();});$('#period').addEventListener('change',e=>{period=e.target.value;render();});$('#mobilevenue').addEventListener('change',e=>{venue=e.target.value;render();});$('#mydaytop').addEventListener('click',()=>{mode='saved';venue='all';period='all';query='';$('#search').value='';$('#period').value='all';render();$('.content').scrollIntoView({behavior:'smooth',block:'start'});});
render();
